// Single source of truth for conversation language handling.
//
// The conversation language is explicit state (conversation.language), chosen
// by the user in the app. It is never inferred from message text, and no agent
// is allowed to switch it. Everything user-facing that is NOT generated by the
// conversation model (emergency advice, error fallbacks) lives here in every
// supported language so it can never come back in the wrong one.

export const DEFAULT_LANGUAGE = 'en-IN';

export const LANGUAGE_NAMES = {
  'en-IN': 'English',
  'hi-IN': 'Hindi',
  'kn-IN': 'Kannada',
  'ta-IN': 'Tamil',
  'te-IN': 'Telugu',
  'mr-IN': 'Marathi',
  'bn-IN': 'Bengali',
  'gu-IN': 'Gujarati',
  'ml-IN': 'Malayalam',
};

export const SUPPORTED_LANGUAGES = Object.keys(LANGUAGE_NAMES);

// Unicode script used by each language, to sanity-check that a reply really is
// in the selected language.
const SCRIPT_REGEX = {
  'en-IN': /[A-Za-z]/g,
  'hi-IN': /[ऀ-ॿ]/g,
  'mr-IN': /[ऀ-ॿ]/g,
  'kn-IN': /[ಀ-೿]/g,
  'ta-IN': /[஀-௿]/g,
  'te-IN': /[ఀ-౿]/g,
  'bn-IN': /[ঀ-৿]/g,
  'gu-IN': /[઀-૿]/g,
  'ml-IN': /[ഀ-ൿ]/g,
};

/** "hi", "hi-in", "HI_IN" … → "hi-IN". Unknown values return null. */
export function normalizeLanguage(lang) {
  if (!lang || typeof lang !== 'string') return null;
  const base = lang.trim().toLowerCase().replace('_', '-').split('-')[0];
  return SUPPORTED_LANGUAGES.find((code) => code.toLowerCase().startsWith(`${base}-`)) || null;
}

export function resolveLanguage(lang, fallback = DEFAULT_LANGUAGE) {
  return normalizeLanguage(lang) || normalizeLanguage(fallback) || DEFAULT_LANGUAGE;
}

export function languageName(lang) {
  return LANGUAGE_NAMES[resolveLanguage(lang)];
}

/**
 * Does `text` read as the selected language? Brand/drug names are usually
 * Latin, so for Indic languages we only require that the target script makes
 * up a clear share of the letters. For English we require mostly Latin letters.
 * Very short strings are given the benefit of the doubt.
 */
export function isInLanguage(text, lang) {
  const code = resolveLanguage(lang);
  const letters = (String(text || '').match(/\p{L}/gu) || []);
  if (letters.length < 8) return true;
  const own = (String(text).match(SCRIPT_REGEX[code]) || []).length;
  return own / letters.length >= (code === 'en-IN' ? 0.85 : 0.35);
}

/** The dominant script bucket of a text — used only to pick a translation source. */
export function looksLatin(text) {
  const letters = String(text || '').match(/\p{L}/gu) || [];
  if (!letters.length) return true;
  return (String(text).match(/[A-Za-z]/g) || []).length / letters.length > 0.6;
}

// ── Emergency advice ─────────────────────────────────────────────────────────
// Deliberately conservative, short and identical in meaning across languages:
// call 112 (national emergency) or 108 (ambulance), or go to the nearest
// hospital now. Wording should be reviewed by native speakers before release.
